changeSet.sql:
UPDATE consent_type_translations
SET description = 'Wyrażam zgodę na otrzymywanie od ELCARO Sp. z o.o. treści marketingowych obejmujących informacje o usługach, produktach, programach i promocjach Spółki.'
WHERE language_code = 'pl' AND code = 'MARKETING';

UPDATE consent_type_translations
SET description = 'Wyrażam zgodę na używanie telekomunikacyjnych urządzeń końcowych i automatycznych systemów wywołujących dla celów marketingu bezpośredniego przez ELCARO Sp. z o.o.'
WHERE language_code = 'pl' AND code = 'PHONE_CONTACT';

UPDATE consent_type_translations
SET description = 'Wyrażam zgodę na otrzymywanie informacji handlowych drogą elektroniczną na udostępniony przeze mnie adres e-mail od ELCARO Sp. z o.o.'
WHERE language_code = 'pl' AND code = 'EMAIL_CONTACT';

UPDATE consent_type_translations
SET description = 'I agree to receive marketing content from ELCARO Sp. z o.o. including information about the Company''s services, products, programs, and promotions.'
WHERE language_code = 'en' AND code = 'MARKETING';

UPDATE consent_type_translations
SET description = 'I agree to the use of telecommunications terminal equipment and automated calling systems for direct marketing purposes by ELCARO Sp. z o.o.'
WHERE language_code = 'en' AND code = 'PHONE_CONTACT';

UPDATE consent_type_translations
SET description = 'I agree to receive commercial information electronically to the email address I provided from ELCARO Sp. z o.o.'
WHERE language_code = 'en' AND code = 'EMAIL_CONTACT';
